window.EXAM_AIDS = {"cards": [{"module": 6, "title": "Sperling: whole and partial report", "pages": [13, 15, 16, 17, 18], "researcher": "Sperling", "aim": "How much does sensory (iconic) memory hold, and how long does it last?", "manipulated": "The report method: whole report (name as many letters as you can), partial report (a tone cues one row right away), and delayed partial report (the tone comes after a delay). The displays were three rows of four letters.", "measured": "How many letters people could report from a briefly flashed letter array.", "found": "In whole report people named about a third of the letters. In partial report they named most of the cued row, for any row. In delayed partial report they named only about one letter, and by about one second partial report fell to near the whole-report level.", "means": "Sensory memory has a large capacity but fast decay; the report limit came from the image fading, not from too little being stored.", "trap": "Whole report makes capacity look like four or five items, but that is a limit on reporting, not on storage."}, {"module": 6, "title": "Brown–Peterson: delay and trial history", "pages": [24, 25, 26, 27, 28, 29, 30], "researcher": "Brown and Peterson and Peterson", "aim": "How fast does short-term memory fade when rehearsal is blocked?", "manipulated": "The delay before recall (a few seconds up to about eighteen seconds) and where a trial fell in the series (first trial, third trial, many trials later).", "measured": "Recall of three letters after counting backward by threes during the delay.", "found": "On the first trial recall stayed high even after the long delay. On later trials recall after the long delay dropped, and after many trials it fell to almost nothing. Averaged over all trials, recall fell with delay.", "means": "Forgetting in short-term memory comes from proactive interference as well as decay; earlier trigrams made the new one harder to keep.", "trap": "The average curve looks like pure decay over time, but it hides that the big drops came from later trials."}, {"module": 6, "title": "Visual change detection and complexity", "pages": [37, 39, 41, 42, 43, 44], "researcher": "Alvarez and Cavanagh", "aim": "Is visual short-term memory capacity set by the number of items or by the amount of information in them?", "manipulated": "Set size (number of colored squares), what changed in colored bars (angle, color, or both), and object complexity (colored squares, Chinese characters, random polygons, shaded cubes).", "measured": "Whether people judged a second display (S2) the same as or different from a briefly flashed first display (S1).", "found": "Accuracy fell dramatically above about four items. Remembering two features of a bar was about as easy as one. Capacity fell as objects got more complex, from about four for colored squares to fewer than two for shaded cubes.", "means": "Visual short-term memory holds about three to four whole objects, and capacity depends on how much information each object carries.", "trap": "Do not say the limit is always seven items; for visual memory the slides give about four, and fewer for complex objects."}, {"module": 6, "title": "Digit-span training and chess expertise", "pages": [45, 46], "researcher": "Ericsson and colleagues; Chase and Simon", "aim": "Can chunking and knowledge let people hold much more in short-term memory?", "manipulated": "For Ericsson: training a college student on digit span. For Chase and Simon: player skill (masters vs beginners) and board type (real-game arrangement vs random arrangement).", "measured": "Digit span for the trained student; number of chess pieces placed correctly after a brief look at a board.", "found": "The trained student's digit span rose to around eighty digits by chunking digits into running times. Masters placed far more pieces than beginners on real-game boards but were no better on random boards.", "means": "Chunking with knowledge from long-term memory stretches capacity; experts do not have bigger short-term memories.", "trap": "The masters' advantage disappears with random boards, so it is knowledge of real patterns, not a larger store."}, {"module": 9, "title": "Conrad · sound-based errors after visual presentation", "pages": [8, 9], "researcher": "Conrad (1964)", "aim": "When letters are seen, are errors based on how they look or how they sound?", "manipulated": "Whether the flashed letters were similar or not similar (half of the presentations each).", "measured": "Writing down the letters after a brief visual flash.", "found": "Errors more often swapped in a letter that sounded like the target (E replaced by B) than one that looked like it (F for E).", "means": "Seen letters are recoded into a sound-based form in working memory (phonological similarity effect).", "trap": "The letters came in through vision, but the confusions followed sound; presentation format is not the same as memory code."}, {"module": 9, "title": "Word length, bilingual digit span, and articulatory suppression", "pages": [10, 11], "researcher": "Baddeley and colleagues (1975, 1984); Ellis and Hennelly (1980)", "aim": "What limits how much verbal material the phonological loop can hold?", "manipulated": "Word length (short vs long words), language of the digits (Welsh vs English for bilingual children), and speaking while memorizing (articulatory suppression).", "measured": "Memory for word lists and digit span.", "found": "People remembered more short words than long words. Welsh-English bilingual children had a shorter digit span in Welsh because Welsh number names take longer to say. Suppression lowered recall and reduced both the word-length and phonological similarity effects.", "means": "Verbal span depends on how much can be rehearsed in about 1.5 to 2 seconds, and speech-based rehearsal is used to maintain verbal information.", "trap": "The Welsh-English gap comes from pronunciation time, not from the numbers' values."}, {"module": 9, "title": "Brooks · sentence and F dual-task comparisons", "pages": [13, 14, 15], "researcher": "Brooks (1968)", "aim": "Does a response interfere more when it uses the same kind of memory as the thing being held?", "manipulated": "Response mode: speaking vs pointing, for two memory tasks (a memorized sentence with noun judgments, and a memorized F with inside/outside corner judgments).", "measured": "How easy each task was under each response mode.", "found": "With the sentence, pointing was easier than speaking. With the F, speaking was easier than pointing.", "means": "Interference depends on the combination of tasks, which supports some independence between verbal and visual or spatial memory.", "trap": "The results reverse across the two tasks, so neither speaking nor pointing is easier overall."}, {"module": 9, "title": "Shepard and Metzler · angle and mental-rotation time", "pages": [17], "researcher": "Shepard and Metzler (1971)", "aim": "Do people mentally rotate objects, and does more rotation take more time?", "manipulated": "The angle of rotation between pairs of block-built objects (picture-plane and depth rotation).", "measured": "Reaction time to judge whether the two objects matched.", "found": "For picture-plane pairs, reaction time increased as the angle increased, approximately linearly.", "means": "Larger angles need a larger mental transformation, consistent with an active operation on a spatial representation.", "trap": "Picture-plane rotation turns within the flat plane; depth rotation turns in three-dimensional space."}, {"module": 9, "title": "Vogel · relevant load, distractors, and filtering efficiency", "pages": [20, 21, 22], "researcher": "Vogel and colleagues (2005)", "aim": "Do people with higher working-memory capacity keep irrelevant items out better?", "manipulated": "Capacity group (higher vs lower) and display type: two relevant red bars, four relevant red bars, or two red bars plus two irrelevant blue bars.", "measured": "A memory-related ERP response during the 900 ms retention interval, plus a change judgment on the relevant orientations.", "found": "High-capacity people showed a larger response for four items than two, and little change when blue distractors were added. For low-capacity people, adding distractors raised the response toward the four-item level. Capacity correlated positively with filtering efficiency.", "means": "Capacity depends on which items get in as well as how many targets there are; better filtering goes with higher capacity.", "trap": "A bigger response means a stronger negative deflection, not a more positive voltage."}, {"module": 10, "title": "Köhler · circle representation and equal diagonals", "pages": [3], "researcher": "Köhler", "aim": "Can reorganizing how a problem is represented make a hidden relationship usable?", "manipulated": "Not a comparison of groups; it is a demonstration of how representing the circle problem as a rectangle changes the solution.", "measured": "Finding the length of line x when the circle's radius is r.", "found": "Seeing the black line as a diagonal of a rectangle makes it equal to the dashed radius (the other diagonal), so x = r.", "means": "Restructuring the representation, not new calculation, makes the answer available.", "trap": "Do not treat x as an isolated unknown inside the circle; the key is spotting the rectangle with equal diagonals."}, {"module": 10, "title": "Metcalfe and Wiebe · insight puzzles and warmth judgments", "pages": [5, 6, 7], "researcher": "Metcalfe and Wiebe (1987)", "aim": "Do people feel gradually closer to a solution for insight problems as they do for noninsight problems?", "manipulated": "Problem type: insight problems (triangle and chain) vs noninsight problems (algebra).", "measured": "Warmth ratings (hot means close to the solution) given every 15 seconds while solving.", "found": "For algebra, warmth rose gradually as the solution approached. For insight problems, warmth stayed low until close to the solution and then jumped sharply, from about 3 to 7.", "means": "Insight solutions come with a sudden change in felt progress, unlike methodical noninsight solving.", "trap": "Not all problem solving is sudden; the sudden jump describes insight problems, not algebra."}, {"module": 10, "title": "Candle problem · matchbox presentation and functional fixedness", "pages": [8], "researcher": "", "aim": "Does seeing an object only in its familiar use block its use for something else?", "manipulated": "Whether the matches were inside the box or the matchboxes were empty.", "measured": "Whether participants solved the problem of mounting the candle on a vertical corkboard so it burns without dripping wax on the floor.", "found": "Participants given empty matchboxes were twice as likely to solve the problem.", "means": "Functional fixedness: treating the box only as a container hides its use as a platform for the candle.", "trap": "The materials were enough to solve it; the obstacle was the familiar use of the box."}, {"module": 10, "title": "Two-string problem · pliers as a weight and a movement hint", "pages": [9, 10], "researcher": "", "aim": "What helps people see a new use for an object in the two-string problem?", "manipulated": "Whether an experimenter 'accidentally' set a string in motion (the hint).", "measured": "Whether participants solved the problem of tying together two strings hanging too far apart to reach.", "found": "After the swinging hint, most participants were able to solve the problem. The solution is to tie the pliers on a string as a weight and make it swing like a pendulum.", "means": "The hint helped restructure the representation, so the string became something that can be swung within reach.", "trap": "The pliers' useful property is their weight, not their ability to grip; that is the functional fixedness."}, {"module": 10, "title": "Water-jug problems · practice and a simpler available solution", "pages": [11], "researcher": "", "aim": "Can a method that worked earlier block a simpler solution?", "manipulated": "Practice with the early problems that Practice with early problems solved by B − A − 2C, then new problems (7 and 8) with capacities where a simpler solution exists.", "measured": "Not measured with participants on the slide; it traces which solution method each problem allows.", "found": "Repeated success with B − A − 2C builds a mental set. In problem 7 the goal 18 can be reached by A + C, and in problem 8 the goal 25 by A − C, but the familiar method still works and is brought first.", "means": "A mental set can inhibit a simpler solution even when the familiar one remains possible.", "trap": "The familiar method still works in problems 7 and 8; the set blocks the simpler one, not the correct answer."}, {"module": 10, "title": "Search demonstrations · tile puzzle and Tower of Hanoi subgoals", "pages": [13, 14, 15, 16, 17, 18], "researcher": "Newell and Simon", "aim": "How can solving be described as search through a problem space using operators and subgoals?", "manipulated": "Nothing varied; these are worked demonstrations with the Tower of Hanoi and a numbered-tile puzzle.", "measured": "Not measured with participants; the slides trace states, legal moves, and subgoals.", "found": "Operators set which moves are legal; routes pass through intermediate states; a search tree shows branches of alternative states. In the Tower of Hanoi, subgoals free the large disk, free the third peg, then move the large disk.", "means": "Means–end analysis reduces the difference between the current state and the goal by achieving subgoals.", "trap": "A subgoal is an intermediate condition that makes a move possible, not the final answer."}, {"module": 10, "title": "Mutilated checkerboard · labels, pairing, and think-aloud protocols", "pages": [19, 20, 21, 22], "researcher": "", "aim": "Does how a problem is stated change how hard it is to find the pairing constraint?", "manipulated": "Information on the board: blank, colored, labeled black and pink, or labeled bread and butter.", "measured": "How fast participants solved the covering problem, along with think-aloud reports of their thoughts.", "found": "Participants solved the bread-and-butter condition twice as fast as the blank condition. Think-aloud reports showed a shift from squares as positions to the relation between the two kinds of square.", "means": "Labels pointing to the right representation (one of each kind per domino) reduce solving time, matching Gestalt restructuring.", "trap": "Equal total area (62 squares, 31 dominoes) does not mean a covering is possible; the colors are unequal."}, {"module": 11, "title": "Marriage and checkerboard · mapping a shared pairing constraint", "pages": [3, 4, 5], "researcher": "", "aim": "Can a solver see why 31 pairs are impossible when the two groups are unequal?", "manipulated": "The number of men and women (32 and 32, then 30 and 32), and the matching board problem with two same-colored corners removed.", "measured": "Whether 31 heterosexual marriages (or 31 dominoes) can be formed.", "found": "No. With 30 men and 32 women, at most 30 marriages are possible. The checkerboard has the same imbalance between square colors, so 31 dominoes cannot cover it.", "means": "The solution comes from the one-of-each pairing relationship, not from total size or area.", "trap": "Total count (62 people or 62 squares) says 31 pairs, but the pairing rule is what decides it."}, {"module": 11, "title": "Duncker and Gick–Holyoak · radiation, fortress, and reminders", "pages": [6, 7, 8, 9, 10], "researcher": "Duncker; Gick and Holyoak", "aim": "Do people notice and use a solved source story (the fortress) to solve the radiation problem?", "manipulated": "Whether participants read the fortress story first, and whether they were told to think about that story.", "measured": "Whether participants reached the converging-rays solution to the radiation problem.", "found": "About 10% solved radiation without the analogy. After reading the fortress story, about 30% solved it. When told to think about the story, about 75% did.", "means": "Having a useful source in memory is not enough. People must notice it and map it to the target.", "trap": "Many people read the source but do not spontaneously use it. The hint is the difference between 30% and 75%."}, {"module": 11, "title": "Lightbulb transfer · surface and structural similarities", "pages": [11, 12, 13, 14, 15, 16], "researcher": "", "aim": "Does a source with similar surface features, or similar structure, help solve a target problem?", "manipulated": "Which source participants knew: radiation, fragile-glass lightbulb, or insufficient-intensity lightbulb. A control group had no source.", "measured": "Whether participants solved the target (lightbulb or radiation).", "found": "81% who knew radiation solved the lightbulb problem, versus 10% in the control group. 69% who read the fragile-glass solution solved radiation, versus 33% after the insufficient-intensity version.", "means": "Matching structure (a strong effect at the target plus protected surroundings) helps more than matching only the objects.", "trap": "Both lightbulb sources use converging lasers, but only the fragile-glass one shares the reason (damage to surroundings)."}, {"module": 11, "title": "In vivo observation · analogies in scientific work", "pages": [17], "researcher": "", "aim": "How often do real scientists use analogies during ordinary work?", "manipulated": "Nothing was manipulated. Researchers observed scientists in real-world lab meetings.", "measured": "The number of analogies used in a one-hour laboratory meeting.", "found": "Scientists use about 3-15 analogies in a one-hour laboratory meeting.", "means": "Analogies are common in real work even though they are hard to transfer in lab tasks (the analogical paradox).", "trap": "In vivo gives real context but little control of variables, and it can be time-consuming."}, {"module": 11, "title": "Chase and Simon · game positions, random layouts, and chunks", "pages": [19], "researcher": "Chase and Simon (1973)", "aim": "Is expert chess recall due to general memory or to organized knowledge?", "manipulated": "Skill (chess master versus a beginner with under 100 hours) and the arrangement type (actual game positions versus random arrangements).", "measured": "Reproducing the piece positions after viewing the board for five seconds.", "found": "The expert did much better than the beginner on actual game positions. The same familiar chunks were not available for random arrangements.", "means": "Expert memory depends on chunks stored in long-term memory, not on a general memory advantage.", "trap": "Do not say experts remember everything better. The advantage is tied to meaningful positions."}, {"module": 11, "title": "Chi and colleagues · surface-based and principle-based sorting", "pages": [20, 21], "researcher": "Chi et al. (1982)", "aim": "Do experts and novices organize physics problems in the same way?", "manipulated": "Group: experts (physics professors) versus novices (students with one semester of physics).", "measured": "Sorting 24 physics problems into groups by similarity.", "found": "Novices grouped by surface features, such as inclined planes. Experts grouped by structural features, such as conservation of energy.", "means": "Expertise changes which relationship is used as the basis for similarity.", "trap": "The same problem 24 pairs with 23 (novice, inclined planes) or with 21 (expert, conservation of energy)."}, {"module": 12, "title": "Availability judgments · letter positions and causes of death", "pages": [6, 7, 8], "researcher": "", "aim": "Do people judge how likely something is by how easily examples come to mind?", "manipulated": "The letter question (r first versus r third) and paired causes of death (for example, botulism versus asthma).", "measured": "Choosing which alternative is more frequent or more likely.", "found": "About 70% say more words begin with r, though words with r third are three times more common. Many pick the dramatic cause of death over the more common one such as asthma.", "means": "Ease of remembering is used as a cue for probability, and it is affected by things other than frequency.", "trap": "Memorable or newsworthy is not the same as common."}, {"module": 12, "title": "Representativeness · Robert, Jack, and Linda", "pages": [9, 10, 11], "researcher": "", "aim": "Do people use resemblance instead of base rates and probability rules?", "manipulated": "The description given (Robert, Jack, Linda) and whether base-rate information was available.", "measured": "Judging occupation (librarian or farmer; engineer or lawyer) or choosing between bank teller and feminist bank teller.", "found": "Many call Robert a librarian despite about 2.2 million farms versus 120,000 libraries. People use the 70/30 base rate alone but ignore it once Jack is described. About 82% choose the conjunction for Linda.", "means": "A fitting description can override base rates and the conjunction rule.", "trap": "Feminist bank teller is a subset of bank teller, so it cannot be more probable."}, {"module": 12, "title": "Hospital samples · extreme proportions and sample size", "pages": [12, 13, 14], "researcher": "", "aim": "Do people consider sample size when judging how often extreme proportions occur?", "manipulated": "Hospital size: about 45 births per day versus about 15 births per day.", "measured": "Choosing which hospital has more days with over 60% boys (larger, smaller, or about the same).", "found": "56% chose about the same. The correct answer is the smaller hospital, because small samples vary more.", "means": "Small samples are more variable, which is why the law of large numbers matters.", "trap": "The question is about days over 60%, not total boys born."}, {"module": 12, "title": "Lord and colleagues · myside bias in article evaluation", "pages": [16], "researcher": "Lord and colleagues (1979)", "aim": "Does an existing opinion change how the same evidence is evaluated?", "manipulated": "Participants' opinion on capital punishment: in favor versus opposed.", "measured": "How each participant interpreted the same article.", "found": "Each side saw the article as favorable to its own position.", "means": "Myside bias is evaluating evidence in a way that favors one's own opinions and attitudes.", "trap": "Both groups read the same article. The difference is in the readers."}, {"module": 12, "title": "Hidden number rule · confirmation and diagnostic tests", "pages": [17], "researcher": "", "aim": "Do people look for evidence that could prove their hypothesis wrong?", "manipulated": "Nothing varied between groups. Participants wrote their own number triples starting from 2, 4, 6.", "measured": "Their triples and the rule they proposed, with feedback on whether each fit the experimenter's rule.", "found": "The most common hypothesis was increasing intervals of two. The actual rule was three numbers in increasing order.", "means": "Testing only triples that fit the hypothesis keeps a too-narrow belief alive. Testing for contradictions is more useful.", "trap": "Repeated 'yes' feedback does not separate the narrow rule from the broader one."}, {"module": 12, "title": "Jellybeans · favorable counts versus winning probability", "pages": [20], "researcher": "", "aim": "Do people choose by the number of winning items or by the probability of winning?", "manipulated": "Two bowls: 1 red bean out of 10 versus 7 red beans out of 100.", "measured": "Which bowl participants chose before drawing.", "found": "Most chose the 7-out-of-100 bowl, though 10% beats 7%.", "means": "A larger count of favorable items draws attention away from the total number of draws.", "trap": "Compare ratios, not counts."}, {"module": 12, "title": "Ritov and Baron · convoy rerouting and lives saved", "pages": [22], "researcher": "Ritov and Baron (1999)", "aim": "Do people choose the option that saves the most lives when it requires causing harm?", "manipulated": "Rerouting a food convoy (saves 1,000 at the second camp, 100 die at the first) versus keeping the route.", "measured": "Whether participants chose to reroute.", "found": "63% did not choose to reroute. Some would keep the route even if only one person would die after the change.", "means": "Reluctance to cause harm can outweigh a larger benefit, so choices are not just about the biggest number.", "trap": "Net lives saved (900) favors rerouting, yet most refused."}, {"module": 12, "title": "Tetlock and colleagues · taboo and tragic outcomes", "pages": [23, 24, 25], "researcher": "Tetlock, Kristel, Elson, Green, and Lerner (2000)", "aim": "How do taboo and tragic tradeoffs affect moral outrage?", "manipulated": "Tradeoff type (taboo: Johnny's life versus hospital money; tragic: two children, one liver) and outcome (Johnny saved or not saved).", "measured": "Ratings of moral outrage.", "found": "In the taboo tradeoff, not saving Johnny produced much greater outrage than saving him. In the tragic tradeoff, outrage was similar whether he was saved or not.", "means": "The effect of the decision depends on the type of value conflict (an interaction).", "trap": "A tragic tradeoff compares two sacred values. A taboo tradeoff puts a sacred value against a secular benefit."}, {"module": 12, "title": "Ginges and colleagues · payment, recognition, and sacred commitments", "pages": [26, 27, 28, 29], "researcher": "Ginges, Atran, Medin, and Shikaki (2007)", "aim": "How do people react to compromise deals over contested issues, and does money help?", "manipulated": "Deal type: taboo, Taboo+ (one billion dollars a year for ten years), and symbolic (recognition and an apology). Participants were also classified as moral absolutists or not.", "measured": "Anger, disgust, and support for violence.", "found": "For moral absolutists, adding money increased anger, disgust, and support for violence. Non-absolutists responded the other way. Symbolic recognition lowered anger or disgust and violence support.", "means": "Money can backfire when the issue is sacred, and symbolic reciprocity can help.", "trap": "Samples were 601 settlers, 535 refugees, and 719 students."}, {"module": 12, "title": "Iranian online study · sacred values, funds, sanctions, and energy results", "pages": [30, 31, 32, 33], "researcher": "Dehghani, Atran, and colleagues (2010); Dehghani, Iliev, and colleagues (2009)", "aim": "Do incentives or sanctions make Iranians who hold a sacred value more willing to give up the nuclear program?", "manipulated": "A 2 x 3 design: program type (energy or weapons) by deal type (Taboo, Taboo+ with 40 billion dollars, Taboo- with the threat of sanctions).", "measured": "Personal approval, anticipated public anger if the government approved, and whether the deal seems misleading.", "found": "For sacred-value participants in the energy condition, approval was lower with funds or sanctions than with the basic deal, and anger was highest with funds. Participants without a sacred value rated approval higher and anger lower.", "means": "For a sacred commitment, improving the material balance does not make a deal more acceptable.", "trap": "Sacred means refusing the exchange no matter how great the consequences. About 14% (energy) and 13% (weapons) did so."}, {"module": 13, "title": "Kermer and colleagues · expected and actual emotions after a coin flip", "pages": [4], "researcher": "Kermer and colleagues (2006)", "aim": "Do people predict their emotions after a win or a loss accurately?", "manipulated": "Outcome of a coin flip: win an extra $5 or lose $3 (after being given $5). Predicted feelings (before the flip) were compared with actual feelings (after).", "measured": "Happiness ratings: a baseline rating before the experiment, then predicted and actual changes from baseline.", "found": "Before the flip, people expected losing $3 to drop happiness about 4 points and winning $5 to raise it about 2 points. After the flip, the real drop was about 1 point and the real rise about 1.2 points.", "means": "People overestimate how bad a loss will feel, because they ignore their coping mechanisms; this feeds risk aversion.", "trap": "The loss was the smaller amount of money ($3 vs $5) but was expected to hurt about twice as much as the gain helped."}, {"module": 13, "title": "Simonsohn · cloudy days, admissions, and enrollment", "pages": [5], "researcher": "Simonsohn (2007); Simonsohn (2009)", "aim": "Does the weather, an incidental factor, carry into important decisions?", "manipulated": "Weather: cloudy vs sunny days (on the day of the admissions decision, or the day of the campus visit).", "measured": "Admissions decisions (what was weighted) and whether visiting students enrolled.", "found": "Simonsohn (2007): applicants' academic attributes were weighted more heavily on cloudy days than sunny days. Simonsohn (2009): visitors to a highly rated university were more likely to enroll if they visited on a cloudy day.", "means": "Weather is an incidental factor that can change important decisions even though it is unrelated to the applicant or the school.", "trap": "Do not mix up the two years: 2007 is admissions decisions, 2009 is enrollment by visitors."}, {"module": 13, "title": "Lerner and colleagues · mood and highlighter prices", "pages": [6], "researcher": "Lerner and colleagues (2004)", "aim": "Can a mood unrelated to the decision change how much an object seems worth?", "manipulated": "Film clip watched first: sad (a person dying), disgust (a person using a dirty toilet), or neutral (fish at the Great Barrier Reef).", "measured": "Selling price and buying price for a set of highlighters.", "found": "Selling: neutral about $4.50, disgust about $2.70, sad about $3.00. Buying: neutral about $3.50, disgust about $3.00, sad about $4.50.", "means": "Incidental mood influences decisions: disgust lowered both prices, and sadness lowered selling but raised buying.", "trap": "Sad lowers the selling price but RAISES the buying price; disgust lowers both."}, {"module": 13, "title": "Physicians · earlier cases and cesarean recommendations", "pages": [7], "researcher": "", "aim": "Does the context of earlier cases change a decision about the same case?", "manipulated": "What came before the same test case: nothing (control), four serious-complication cases, or four fairly routine (not serious) cases.", "measured": "Whether physicians recommended a cesarean section for the test case.", "found": "Significantly more doctors recommended cesarean after reading the non-serious cases first.", "means": "Context, including recently considered cases, changes how the same patient is judged.", "trap": "The test case never changed; only the cases before it did."}, {"module": 13, "title": "Organ donation · opt-in and opt-out consent", "pages": [8], "researcher": "", "aim": "Does the way the choice is presented change how many people become organ donors?", "manipulated": "Opt-in procedure (must take a step to be a donor) vs opt-out procedure (a donor unless you ask not to be).", "measured": "Consent rate in countries using each procedure.", "found": "Opt-in countries have under 28% consent; opt-out countries have over 99% consent.", "means": "The status quo bias, the tendency to do nothing when a decision is difficult, makes the default decide the result.", "trap": "Doing nothing means non-donor under opt-in but donor under opt-out."}, {"module": 13, "title": "Tversky and Kahneman · the disease problem in gain and loss frames", "pages": [9, 11, 12], "researcher": "Tversky and Kahneman (1981)", "aim": "Does describing the same outcomes as gains or as losses change risk-taking?", "manipulated": "Frame: gain frame (A: 200 saved for certain; B: 1/3 chance all 600 saved, 2/3 chance none) vs loss frame (C: 400 die for certain; D: 1/3 chance no one dies, 2/3 chance all 600 die).", "measured": "Which program people chose.", "found": "Gain frame: 72% chose A (sure), 28% chose B. Loss frame: 78% chose D (gamble), 22% chose C.", "means": "The framing effect: gains push people to risk aversion (sure thing), losses push them to risk taking (gamble), though A=C and B=D.", "trap": "A and C are the same outcome, and B and D are the same gamble; only the wording changed."}, {"module": 13, "title": "Sanfey and colleagues · the ultimatum game and the anterior insula", "pages": [14, 15], "researcher": "Sanfey and colleagues (2003)", "aim": "Do emotion and brain activity explain why people reject unfair offers that cost them money?", "manipulated": "Offer size ($5/$5, $7/$3, $8/$2, $9/$1) and partner type (human vs computer); each participant played 20 games, 10 with each partner type.", "measured": "Whether the responder accepted or rejected, plus activation of the right anterior insula.", "found": "$5/$5 and $7/$3 were accepted almost always. $8/$2 was accepted about 53% (human) vs 85% (computer); $9/$1 about 37% (human) vs 68% (computer). More right anterior insula activation meant rejecting more offers.", "means": "Emotion (anger at unfairness) is important in decision making; utility theory says accept any offer, but people do not.", "trap": "Utility theory says accept any offer because any money beats nothing; rejecting costs both players."}, {"module": 13, "title": "Belief bias · judging invalid believable conclusions", "pages": [18], "researcher": "", "aim": "Does a believable conclusion make people accept a syllogism as valid?", "manipulated": "Invalid syllogisms with believable conclusions.", "measured": "Whether participants judged the syllogism valid.", "found": "71% judged invalid syllogisms with believable conclusions as valid.", "means": "Belief bias: people judge by whether the conclusion sounds true instead of whether it follows.", "trap": "Example: All of the students are tired / Some tired people are irritable / Some of the students are irritable sounds fine but is not valid."}, {"module": 13, "title": "Conditional syllogisms · four forms and accuracy", "pages": [22, 23, 24, 25], "researcher": "", "aim": "Which kinds of if-then syllogisms do people judge correctly?", "manipulated": "The four forms, all with If p, then q: p (modus ponens), not q (modus tollens), q, and not p.", "measured": "Whether participants judged each form valid or invalid correctly.", "found": "Modus ponens (valid) 97% correct; modus tollens (valid) 60%; syllogism 3 (invalid) 40%; syllogism 4 (invalid) 40%.", "means": "Both valid forms were judged correctly more often than both invalid ones, but modus tollens is much harder than modus ponens even though both are valid.", "trap": "Modus tollens is valid; syllogisms 3 and 4 are not."}, {"module": 13, "title": "Wason four-card problem · abstract and concrete versions", "pages": [26, 27, 28], "researcher": "", "aim": "Does using real-world items make conditional reasoning easier?", "manipulated": "Abstract version (cards E, K, 4, 7; rule: vowel then even number) vs concrete version (cards Beer, Soda, 16 years old, 21 years old; rule: drinking beer then 21 years old).", "measured": "Which cards participants chose to turn over.", "found": "Abstract: 46% chose 4 (error), only 7% chose 7 (correct). Concrete: 73% answered correctly.", "means": "Following the falsification principle, look for cases that break the rule; permission schemas in familiar rules make this easier.", "trap": "Correct cards are E and 7 (abstract) and beer and 16 years old (concrete); the 4 and the 21 cannot break the rule."}, {"module": 14, "title": "Phonological Similarity Effect", "pages": [1], "researcher": "Conrad (1964); Murray (1968)", "aim": "Show that people recode silently read items into a speech-based form.", "manipulated": "Lists of letters that sound alike versus sound different. On some trials people also said 'one, two, three, four' out loud (articulatory suppression) and on others stayed quiet.", "measured": "How well people clicked the letters back in the order shown.", "found": "Sound-alike lists were recalled worse, even when read silently. With suppression on visual lists, the cost disappeared.", "means": "People turn what they see into a sound code, which supports the phonological loop.", "trap": "It is about similar sound, not similar look (E and F would be a visual mix-up)."}, {"module": 14, "title": "Neighborhood Size Effect", "pages": [2], "researcher": "Roodenrys et al. (2002)", "aim": "Test whether long-term knowledge of words affects short-term recall.", "manipulated": "Words from large neighborhoods (like cat) versus small neighborhoods (like hippopotamus).", "measured": "How well people recalled the words in order.", "found": "Large neighborhood words were recalled better in short-term memory tasks.", "means": "What you know in long-term memory helps short-term recall, so memory span is not a pure measure of short-term capacity.", "trap": "A neighbor differs by one letter or one sound; do not confuse it with a word that merely means the same thing."}, {"module": 14, "title": "Brown-Peterson Task", "pages": [3], "researcher": "Peterson and Peterson (1959)", "aim": "Find out what happens to short-term memory when rehearsal is blocked.", "manipulated": "How long people did a distractor task (counting backwards) before recall.", "measured": "How well people recalled the consonants.", "found": "The longer the distraction, the worse the recall.", "means": "The researchers concluded short-term memory loses information through decay unless it is rehearsed.", "trap": "Decay is the researchers' conclusion, and interference (Keppel and Underwood, 1962) was cited as an alternative."}, {"module": 14, "title": "Modality Effect", "pages": [4], "researcher": "", "aim": "Test whether hearing a list gives better memory than reading it.", "manipulated": "Lists that were heard versus read silently (digits in random order).", "measured": "Memory for the last one or two items.", "found": "Heard lists gave better memory for the last items. Lip-read or mouthed lists show it too.", "means": "Hearing adds information about how the list sounded (Neath and Surprenant, 2003), and the effect shaped ideas about sensory memory.", "trap": "The effect is for the last items of the list, not the whole list."}, {"module": 14, "title": "Partial Report", "pages": [5], "researcher": "Sperling (1960)", "aim": "Test whether the small amount people report from a brief display is a recall limit or a perception limit.", "manipulated": "Whether a cue telling which part to report came right away or after a delay.", "measured": "How much of the cued part people reported.", "found": "With an immediate cue, people reported the cued part almost perfectly. With a delayed cue, performance fell toward the usual limit.", "means": "A sensory (iconic) store briefly held nearly all the display, and it fades very fast. The limit is reporting time, not perception.", "trap": "The limit is in recall, not in what people saw."}, {"module": 14, "title": "Position Error Effect", "pages": [6], "researcher": "", "aim": "Show how order errors in recall are patterned.", "manipulated": "Nothing was compared across groups. Each recalled letter's placed position was compared with its true position.", "measured": "Where each recalled item was placed in the list.", "found": "Items were usually placed correctly. Errors were systematic: the item landed in an adjacent position.", "means": "People keep approximate position information, and percent correct alone hides this.", "trap": "Order errors are not random."}, {"module": 14, "title": "Mental Rotation", "pages": [7], "researcher": "Shepard and Metzler (1971)", "aim": "Test whether mental images behave like real images.", "manipulated": "How much one block shape was turned relative to the other (same shape or mirror image).", "measured": "How long people took to judge same or mirror image.", "found": "The larger the turn, the longer the response, at a constant rate.", "means": "People mentally rotate images, so mental images are much like real images.", "trap": "Self-reports of imagery are unreliable, so researchers use tasks that require imagery."}, {"module": 14, "title": "Typical Reasoning", "pages": [8], "researcher": "Tversky and Kahneman (1983); Shafir, Smith, and Osherson (1990)", "aim": "Show that people judge probability with heuristics.", "manipulated": "People rated how likely descriptions of a person were to fit single professions or activities versus combinations.", "measured": "Ratings of how likely each statement was.", "found": "People sometimes rated a combination as more likely than one of its parts (conjunction fallacy).", "means": "People use heuristics, not the rules of probability.", "trap": "A combination can never be more likely than either part alone."}, {"module": 14, "title": "Wason Selection", "pages": [9], "researcher": "Wason and Shapiro (1971)", "aim": "Compare how well people test abstract rules and familiar thematic rules.", "manipulated": "Abstract rules (letters and numbers) versus thematic rules (like borrowing a car).", "measured": "Which cards people chose to turn over.", "found": "Thematic rules were much easier. On the abstract rule most people chose D and 3 instead of D and 7.", "means": "With relevant experience people test rules well; with abstract rules they must use logic alone.", "trap": "The 3 can only confirm the rule; the 7 could falsify it."}, {"module": 14, "title": "Decision Making", "pages": [10], "researcher": "Kahneman and Tversky (1982); Tversky and Kahneman", "aim": "Show that wording or context can change choices between equivalent options.", "manipulated": "The same choice framed with gain wording versus loss wording.", "measured": "Which option people chose.", "found": "Gain wording led to the sure option and loss wording to the gamble.", "means": "Choices can follow the framing and not the substance.", "trap": "The situations are otherwise equivalent."}, {"module": 14, "title": "Monty Hall", "pages": [11], "researcher": "", "aim": "Show poor intuition about the probability of combined events.", "manipulated": "Whether people stayed with their first door or switched after the host opened a no-prize door.", "measured": "How often staying and switching won.", "found": "Switching wins about two-thirds of the time and staying about one-third. Many people think it makes no difference.", "means": "The first pick stays at 1 in 3, so the other 2 in 3 moves to the remaining door.", "trap": "The two remaining doors are not equally likely."}, {"module": 14, "title": "Risky Decisions", "pages": [12], "researcher": "Kahneman and Tversky", "aim": "Show that risky choices depend on whether outcomes are seen as gains or losses.", "manipulated": "Whether the sure outcome was a gain or a loss, with a gamble as the alternative.", "measured": "Whether people took the sure thing or the gamble.", "found": "People avoided risk with gains (sure thing) and sought risk with losses (gamble).", "means": "Risk decisions depend on how outcomes are perceived, not only on objective odds.", "trap": "Losses lead to gambling, not caution."}, {"module": 14, "title": "German & Defeyter (2000): Immunity to functional fixedness in young children", "pages": [13], "researcher": "German and Defeyter (2000)", "aim": "Test whether young children get stuck on an object's usual function (functional fixedness).", "manipulated": "Whether the box had first been shown as a container (preutilization) or not, in 5-, 6- and 7-year-olds.", "measured": "How long children took to offer the box as a support.", "found": "Children aged 6 and 7 were slower after seeing the box as a container. 5-year-olds were not slowed and were even faster than the older children after seeing the box as a container.", "means": "Younger children have a more fluid idea of function, so one shown use did not lock the object in.", "trap": "Younger children did better here, not worse."}, {"module": 14, "title": "Leist et al. (2022): Irrelevant speech impairs serial recall of verbal but not spatial items", "pages": [14], "researcher": "Leist et al. (2022)", "aim": "Find out whether ignored speech hurts only verbal items or spatial items too.", "manipulated": "Verbal versus spatial items; quiet, steady-state or changing-state speech to ignore; third graders versus adults.", "measured": "Serial recall of the order of the items.", "found": "Speech hurt verbal recall but not spatial recall, in children and adults.", "means": "The effect is specific to verbal material, which fits phonological interference better than attention capture or changing-state accounts.", "trap": "Changing-state speech hurts more than steady-state, but only for verbal items."}, {"module": 14, "title": "Morrison & Richmond (2020): Offloading items from memory", "pages": [15], "researcher": "Morrison and Richmond (2020)", "aim": "Find out who offloads items from memory and whether it helps.", "manipulated": "A no-choice block (memory only) versus a choice block where pen and paper were allowed, with lists of different lengths.", "measured": "Recall and how much people wrote things down.", "found": "Offloading improved memory, especially at high loads, and people offloaded more as load grew.", "means": "Memory ability did not predict who offloaded, so offloading may be a compensatory strategy across abilities.", "trap": "Low-capacity people were expected to offload more, but capacity did not predict it."}, {"module": 14, "title": "Hoover & Healy (2019): The Bat-and-Ball Problem", "pages": [16], "researcher": "Hoover and Healy (2019)", "aim": "Test whether the bat-and-ball error comes from unconsciously ignoring 'more than'.", "manipulated": "A standard problem with 'more than' versus a control version without it.", "measured": "Confidence, and later recall and recognition of the problem wording.", "found": "Wrong reasoners mostly remembered 'more than', so it was not simply overlooked.", "means": "Substitution cannot be confirmed as the cause, so the authors prefer the term error sensitivity.", "trap": "The intuitive 10 cents is wrong; the answer is 5 cents."}, {"module": 14, "title": "Giuliani et al. (2023): The joint effect of framing and defaults on choice behavior", "pages": [17], "researcher": "Giuliani et al. (2023)", "aim": "Test the framing effect and the default effect together.", "manipulated": "Gain versus loss wording, and no default, a sure default or a risky default, in life-or-death and money scenarios.", "measured": "Whether people chose the sure or the risky option.", "found": "A risky default raised risk taking, a sure default did not raise risk aversion, and framing and default effects were additive.", "means": "People who thought the default was most rational followed it most, though that question came after the choice.", "trap": "The belief question was exploratory and may be a justification."}, {"module": 14, "title": "Chein et al. (2011) and Albert, Chein & Steinberg (2013): Peers and the adolescent brain", "pages": [18], "researcher": "Chein et al. (2011); Albert, Chein and Steinberg (2013)", "aim": "Explain why adolescents take more risks with peers around.", "manipulated": "Playing a driving game alone versus watched by friends, in adolescents, young adults and adults.", "measured": "Risky driving choices and brain activity in reward and cognitive-control regions.", "found": "Adolescents took more risks when watched, with greater reward-region activity. Cognitive-control regions did not change with peers.", "means": "The peer effect works mainly through reward circuitry, not weaker reasoning.", "trap": "Adolescents reason about risk like adults in the lab; the peer context is what changes."}], "contrasts": [{"module": 6, "title": "Whole report vs partial report", "a": {"term": "Whole report", "definition": "The person names as many letters as possible from the flashed array."}, "b": {"term": "Partial report", "definition": "A tone cues one row to report, so only that row is named."}, "tell": "Whole report gave about a third of the letters, partial report gave most of the cued row. The gap shows that more was stored than people could report.", "example": "Sperling's three rows of four letters: the top row was cued by a tone."}, {"module": 6, "title": "Maintenance rehearsal vs elaborative rehearsal", "a": {"term": "Maintenance rehearsal", "definition": "Repeating information silently so it stays in short-term memory longer."}, "b": {"term": "Elaborative rehearsal", "definition": "Linking new information to knowledge already in long-term memory."}, "tell": "Maintenance only keeps information alive while the repeating continues. Elaborative adds meaning and helps move information into long-term memory.", "example": "Saying a phone number over and over is maintenance; connecting it to something you already know is elaborative."}, {"module": 6, "title": "Retroactive vs proactive interference", "a": {"term": "Retroactive interference", "definition": "A new memory interferes with remembering old information."}, "b": {"term": "Proactive interference", "definition": "An old memory interferes with remembering new information."}, "tell": "Ask which memory is doing the interfering. New hurting old is retroactive; old hurting new is proactive.", "example": "A new phone number crowding out the old one is retroactive; earlier trigrams harming the current one in Brown-Peterson is proactive."}, {"module": 6, "title": "Decay vs interference", "a": {"term": "Decay", "definition": "A memory trace vanishes simply because time passes."}, "b": {"term": "Interference", "definition": "Forgetting caused by one memory competing with or replacing another."}, "tell": "Decay depends on time alone; interference depends on what else is in memory. Brown and Peterson and Peterson meant to test decay but found interference as well.", "example": "Recall after the long delay was fine on the first trial but near zero many trials later."}, {"module": 6, "title": "Icon vs echo", "a": {"term": "Icon", "definition": "A fleeting mental image; the visual form of sensory memory."}, "b": {"term": "Echo", "definition": "The brief continuation of a sound in the auditory system."}, "tell": "Icon is for seeing and echo is for hearing; both are sensory memory lasting under a second.", "example": "Sperling studied iconic memory; replaying the last few words someone said is an echo."}, {"module": 6, "title": "Episodic vs semantic memory", "a": {"term": "Episodic memory", "definition": "Memory for personal events we lived through."}, "b": {"term": "Semantic memory", "definition": "Memory for facts and general knowledge."}, "tell": "Episodic ties to a particular time and place; semantic is general knowledge.", "example": "Remembering one particular birthday is episodic; knowing what a birthday is is semantic."}, {"module": 9, "title": "Phonological loop vs visuospatial sketchpad", "a": {"term": "Phonological loop", "definition": "Maintains verbal and auditory information, with a phonological store and articulatory rehearsal."}, "b": {"term": "Visuospatial sketchpad", "definition": "Holds visual and spatial information such as appearance and arrangement."}, "tell": "Ask whether the content is sounds and words or shapes and locations. Brooks's reversed results show they are partly separate.", "example": "A remembered sentence uses the loop; the remembered F uses the sketchpad."}, {"module": 9, "title": "Word-length effect vs phonological similarity effect", "a": {"term": "Word-length effect", "definition": "Lists of short words are remembered better than lists of long words."}, "b": {"term": "Phonological similarity effect", "definition": "Items that sound alike are confused."}, "tell": "Word length is about rehearsal time; similarity is about overlapping sounds. Articulatory suppression reduces both.", "example": "Welsh digits take longer to say, so span is shorter; E is confused with B because they sound alike."}, {"module": 10, "title": "Functional fixedness vs mental set", "a": {"term": "Functional fixedness", "definition": "Restricting an object to its familiar functions."}, "b": {"term": "Mental set", "definition": "A preconceived notion about how to approach a problem, based on past experience with that problem or similar problems."}, "tell": "Fixedness is about an object's use; a set is about a method of solving.", "example": "Seeing the matchbox only as a container is fixedness; repeating B − A − 2C in the water-jug problems is a set."}, {"module": 10, "title": "Insight vs noninsight problems", "a": {"term": "Insight problem", "definition": "Solved by a sudden realization after restructuring, as in the triangle and chain problems."}, "b": {"term": "Noninsight problem", "definition": "Solved by successive operations that bring the solver closer, as in algebra."}, "tell": "Look at warmth: it rises gradually for noninsight problems but jumps late, from about 3 to 7, for insight problems.", "example": "Metcalfe and Wiebe (1987) compared the triangle and chain problems with algebra."}, {"module": 12, "title": "Availability heuristic vs representativeness heuristic", "a": {"term": "Availability heuristic", "definition": "Judging how likely something is by how easily examples come to mind."}, "b": {"term": "Representativeness heuristic", "definition": "Judging whether A belongs to class B by how much A resembles B."}, "tell": "Ask what supplies the shortcut. Remembered examples means availability. Similarity to a type means representativeness.", "example": "Botulism in the news (availability) versus Robert resembling a librarian (representativeness)."}, {"module": 11, "title": "Surface features vs structural features", "a": {"term": "Surface features", "definition": "The specific elements of a problem, such as a fortress, a tumor, or a ray."}, "b": {"term": "Structural features", "definition": "The underlying principle that governs the solution."}, "tell": "Surface is what the objects are. Structure is why a solution works.", "example": "Lightbulb and laser are surface. A strong beam harming the surroundings is structural."}, {"module": 11, "title": "Noticing vs mapping vs applying an analogy", "a": {"term": "Noticing", "definition": "Recognizing that a source problem may be relevant to the target."}, "b": {"term": "Mapping and applying", "definition": "Linking elements of the source to the target, then using that link to build a solution."}, "tell": "Noticing is finding the source. Mapping is lining up the parts. Applying is using them.", "example": "About 30% solved radiation after the fortress story, and about 75% when told to think about it."}, {"module": 11, "title": "Analogical source vs target", "a": {"term": "Source problem", "definition": "A problem with relevant similarities whose solution guides a new problem."}, "b": {"term": "Target problem", "definition": "The problem currently being solved."}, "tell": "The target is what you need to solve now. The source is what you already know.", "example": "Russian marriage is the source and the mutilated checkerboard is the target."}, {"module": 12, "title": "Base rate vs description information", "a": {"term": "Base rate", "definition": "The background prevalence of categories, such as 70 lawyers and 30 engineers."}, "b": {"term": "Description information", "definition": "Personal characteristics, such as Jack's hobbies, that resemble a category."}, "tell": "Base rate says how common the category is. The description says how well the person fits it.", "example": "People use 70/30 alone but call Jack an engineer once he is described."}, {"module": 12, "title": "Conjunction rule vs representativeness", "a": {"term": "Conjunction rule", "definition": "The probability of two events together cannot exceed either one alone."}, "b": {"term": "Representativeness", "definition": "Seeing a more detailed, better-fitting story as more probable."}, "tell": "The rule is about nested sets. Representativeness is about fit.", "example": "About 82% chose feminist bank teller over bank teller for Linda."}, {"module": 12, "title": "Confirmation bias vs myside bias", "a": {"term": "Confirmation bias", "definition": "Seeking information that fits a hypothesis and overlooking what argues against it."}, "b": {"term": "Myside bias", "definition": "Generating and evaluating evidence, and testing hypotheses, in ways biased toward one's own opinions and attitudes."}, "tell": "Myside bias is one form of confirmation bias, tied to one's own opinions and attitudes.", "example": "2, 4, 6 task (confirmation) versus capital punishment article (myside)."}, {"module": 12, "title": "Taboo tradeoff vs tragic tradeoff", "a": {"term": "Taboo tradeoff", "definition": "Mixes sacred and secular domains, such as a child's life against money."}, "b": {"term": "Tragic tradeoff", "definition": "Compares two sacred values with each other."}, "tell": "Ask whether the competing item is a secular benefit (taboo) or another sacred value (tragic).", "example": "Johnny's liver costing one million dollars versus two children and one liver."}, {"module": 12, "title": "Moral absolutists vs non-absolutists", "a": {"term": "Moral absolutists", "definition": "Treat the issue as a sacred value and reject compromise regardless of benefit."}, "b": {"term": "Non-absolutists", "definition": "Have strong preferences against compromise but do not treat the issue as sacred."}, "tell": "Ask whether benefits can enter the decision at all, not how much the person cares.", "example": "Adding money to Taboo+ raised anger for absolutists and lowered it for non-absolutists."}, {"module": 12, "title": "Material incentive vs symbolic recognition", "a": {"term": "Material incentive (Taboo+)", "definition": "Money added to the deal, such as one billion dollars a year for ten years."}, "b": {"term": "Symbolic recognition", "definition": "Recognition of the other group's right and an apology, with no added cash."}, "tell": "Money changes the economic benefit. Symbolic terms address the status of a group's claim.", "example": "Taboo+ raised absolutists' anger, while the symbolic offer lowered anger and support for violence."}, {"module": 12, "title": "Incentive (Taboo+) vs disincentive (Taboo-)", "a": {"term": "Incentive", "definition": "A benefit offered for agreeing, such as 40 billion dollars in funds."}, "b": {"term": "Disincentive", "definition": "A cost imposed for refusing, such as additional sanctions."}, "tell": "Incentives change the benefit of accepting. Disincentives change the cost of refusing.", "example": "Iran study: Taboo+ gave funds and Taboo- threatened sanctions."}, {"module": 11, "title": "Expert vs novice problem organization", "a": {"term": "Experts", "definition": "Group problems by structural features, such as conservation of energy."}, "b": {"term": "Novices", "definition": "Group problems by surface features, such as inclined planes."}, "tell": "Novices go by what the problem looks like. Experts go by the principle that solves it.", "example": "Chi et al. (1982): problems 23 and 24 (novice) versus 21 and 24 (expert)."}, {"module": 13, "title": "Valid vs true", "a": {"term": "Valid", "definition": "The conclusion follows logically from the two premises; depends on the form of the reasoning."}, "b": {"term": "True", "definition": "The statements match the world."}, "tell": "Ask two separate questions: does it follow? and are the statements correct? A valid syllogism with a false premise can have a false conclusion.", "example": "All birds are animals / All animals have four legs / All birds have four legs is valid but its conclusion is false because premise 2 is false."}, {"module": 13, "title": "Modus ponens vs modus tollens", "a": {"term": "Modus ponens", "definition": "If p, then q; p; therefore q. Valid; 97% correct."}, "b": {"term": "Modus tollens", "definition": "If p, then q; not q; therefore not p. Valid; 60% correct."}, "tell": "Ponens affirms p and gets q. Tollens denies q and gets not p. Both are valid; tollens just feels harder.", "example": "If I study, I'll get a good grade; I didn't get a good grade; therefore I didn't study."}, {"module": 13, "title": "Modus tollens vs syllogism 3 (q, therefore p)", "a": {"term": "Modus tollens", "definition": "Second premise is not q; conclusion not p. Valid."}, "b": {"term": "Syllogism 3", "definition": "Second premise is q; conclusion p. Not valid."}, "tell": "Valid forms move from p to q or from not q to not p. Going from q back to p is not valid because there may be other ways to get q.", "example": "If I live in Tucson, then I live in Arizona; I live in Arizona; therefore I live in Tucson does not follow."}, {"module": 13, "title": "Syllogism 3 vs syllogism 4", "a": {"term": "Syllogism 3", "definition": "If p then q; q; therefore p. Not valid; 40% correct."}, "b": {"term": "Syllogism 4", "definition": "If p then q; not p; therefore not q. Not valid; 40% correct."}, "tell": "Both are invalid. In 3 the second premise is q; in 4 it is not p.", "example": "Syllogism 4: If I study, I'll get a good grade; I didn't study; therefore I didn't get a good grade (a good grade could come another way)."}, {"module": 13, "title": "Deductive reasoning vs belief bias", "a": {"term": "Deductive reasoning", "definition": "Determining whether a conclusion logically follows from premises."}, "b": {"term": "Belief bias", "definition": "Thinking a syllogism is valid because its conclusion is believable."}, "tell": "Deduction asks if the conclusion follows. Belief bias answers by asking if the conclusion sounds true.", "example": "71% judged invalid syllogisms with believable conclusions as valid."}, {"module": 13, "title": "Abstract vs concrete Wason problem", "a": {"term": "Abstract version", "definition": "Cards E, K, 4, 7 with the rule vowel then even number; correct cards E and 7."}, "b": {"term": "Concrete version", "definition": "Cards Beer, Soda, 16 years old, 21 years old with the rule drinking beer then 21 years old; correct cards beer and 16."}, "tell": "Same if p, then q form. Concrete, familiar content calls up a permission schema and correct answers jump (73% answered the beer version correctly; only 7% chose the 7 in the abstract version).", "example": "7% chose the 7 in the abstract version; 73% answered the beer version correctly."}, {"module": 13, "title": "Mental models vs belief bias", "a": {"term": "Mental model approach", "definition": "Build a model of the premises, make a tentative conclusion, search for exceptions, then decide validity."}, "b": {"term": "Belief bias", "definition": "The tendency to think a syllogism is valid if its conclusion is believable."}, "tell": "The mental model approach decides validity by searching for an exception; belief bias decides by whether the conclusion sounds believable.", "example": "A conclusion is valid only if no model of the premises refutes it."}, {"module": 13, "title": "Gain frame vs loss frame", "a": {"term": "Gain frame", "definition": "Outcomes stated as people saved; people prefer the sure option (risk aversion)."}, "b": {"term": "Loss frame", "definition": "Outcomes stated as people who die; people prefer the gamble (risk taking)."}, "tell": "Same facts, different wording. Gains lead to the sure thing, losses lead to the gamble.", "example": "72% chose sure Program A; 78% chose gamble Program D."}, {"module": 13, "title": "Opt-in vs opt-out", "a": {"term": "Opt-in", "definition": "You must take a step to be a donor; under 28% consent."}, "b": {"term": "Opt-out", "definition": "You are a donor unless you request not to be; over 99% consent."}, "tell": "Look at what doing nothing gives you. Status quo bias: many people do nothing.", "example": "Doing nothing leaves you a non-donor under opt-in and a donor under opt-out."}, {"module": 13, "title": "Expected emotions vs incidental emotions", "a": {"term": "Expected emotions", "definition": "Emotions people predict they will feel about an outcome."}, "b": {"term": "Incidental emotions", "definition": "Emotions not specifically related to the decision (disposition, recent experience, surroundings)."}, "tell": "Expected emotions are predictions about the outcome itself. Incidental emotions come from something unrelated.", "example": "Kermer: predicted feelings about a coin flip. Lerner: mood from a film clip."}, {"module": 14, "title": "Decay vs interference", "a": {"term": "Decay", "definition": "Information fades from short-term memory over time unless it is rehearsed."}, "b": {"term": "Interference", "definition": "Forgetting caused by other material getting in the way of the memory."}, "tell": "Decay depends on time passing; interference depends on competing material. Peterson and Peterson (1959) chose decay because counting backwards is so unlike remembering letters.", "example": "Recall got worse the longer the counting lasted, which they took as decay."}, {"module": 14, "title": "Phonological code vs visual code", "a": {"term": "Phonological code", "definition": "A speech-based form of the items."}, "b": {"term": "Visual code", "definition": "A memory of how items look."}, "tell": "With a sound code, sound-alike items get confused; with a visual code, look-alike items would. The sound-alike cost on silently read lists shows a sound code.", "example": "E and F look alike, but similar-sounding letters were the ones recalled worse."}, {"module": 14, "title": "Sensory store vs short-term store", "a": {"term": "Sensory (iconic) store", "definition": "A very brief back-up store of raw, unanalyzed input that held nearly all of a display."}, "b": {"term": "Short-term store", "definition": "Holds information briefly for use, and loses it unless rehearsed."}, "tell": "The sensory store fades very quickly, while rehearsal can keep short-term traces.", "example": "In Sperling's (1960) partial report, an immediate cue let people report the cued row almost perfectly."}, {"module": 14, "title": "Phonological similarity vs neighborhood size", "a": {"term": "Phonological similarity effect", "definition": "Sound-alike items are recalled worse."}, "b": {"term": "Neighborhood size effect", "definition": "Words with many neighbors are recalled better."}, "tell": "One shows sound similarity hurting recall; the other shows long-term word knowledge helping recall.", "example": "Lists of sound-alike letters do worse; cat is recalled better than hippopotamus."}, {"module": 14, "title": "Framing effect vs default effect", "a": {"term": "Framing effect", "definition": "Choice changes with the wording or context of equivalent options (gain wording gives the sure option, loss wording the gamble)."}, "b": {"term": "Default effect", "definition": "A tendency to choose the preselected option."}, "tell": "Framing is about how options are described; the default is about which option is already chosen. Giuliani et al. (2023) found the two effects were additive.", "example": "A risky default raised risk taking on top of the framing effect."}, {"module": 14, "title": "Substitution vs error sensitivity", "a": {"term": "Unconscious attribute substitution", "definition": "Answering an easier question because 'more than' is neglected."}, "b": {"term": "Error sensitivity", "definition": "The term Hoover and Healy (2019) prefer because substitution cannot be confirmed as the cause of the error."}, "tell": "Substitution claims a cause; error sensitivity only says people notice they may be wrong. Wrong reasoners mostly remembered 'more than'.", "example": "Hoover and Healy found 'more than' was mostly recalled, so it was not just overlooked."}, {"module": 14, "title": "Reward system vs cognitive control", "a": {"term": "Reward system", "definition": "Ventral striatum and orbitofrontal cortex, primed by peers."}, "b": {"term": "Cognitive-control system", "definition": "Lateral prefrontal cortex, which matures slowly."}, "tell": "In Chein et al. (2011) reward regions rose when friends watched; cognitive-control regions did not change.", "example": "Adolescents watched by friends took more risks, with more reward-region activity."}, {"module": 14, "title": "Offloading vs rehearsal", "a": {"term": "Offloading", "definition": "Using actions like writing things down to reduce mental demands."}, "b": {"term": "Rehearsal", "definition": "Repeating information mentally to keep it from being lost."}, "tell": "Offloading puts the load outside the head; rehearsal keeps it in the head. Offloading helped most at high loads (Morrison and Richmond, 2020).", "example": "With pen and paper allowed, memory improved when lists got long."}, {"module": 14, "title": "Verbal vs spatial items", "a": {"term": "Verbal items", "definition": "Word-like items, such as pictured objects."}, "b": {"term": "Spatial items", "definition": "Locations, such as dot positions."}, "tell": "Ignored speech hurt verbal recall only (Leist et al., 2022), which points to interference with phonological codes.", "example": "Third graders and adults were hurt on objects but not on dot locations."}, {"module": 14, "title": "Falsify vs confirm", "a": {"term": "Falsify", "definition": "Choose the cards that could show the rule is broken (D and 7)."}, "b": {"term": "Confirm", "definition": "Choose a card that can only agree with the rule (the 3)."}, "tell": "The 7 could break the rule; the 3 cannot, since the rule says nothing about what is behind a 3.", "example": "Most people add the 3 to D on the abstract rule; the correct pair is D and 7."}], "ask": [{"module": 6, "topic": "Memory systems and control processes", "questions": ["Which stage of the modal model holds about five to seven items for roughly fifteen to twenty seconds?", "What is the difference between maintenance rehearsal and elaborative rehearsal?", "Why is rehearsal called a control process?", "What is the role of attention between sensory memory and short-term memory?", "Which concept is this an example of: placing items along an imagined building to make them memorable?"], "remember": "The modal model runs sensory, then short-term, then long-term memory; attention gets items into short-term memory, and rehearsal and other control processes are chosen by the person."}, {"module": 6, "topic": "Sensory memory and Sperling", "questions": ["What did Sperling find about whole report compared with partial report?", "What was manipulated in Sperling's experiment?", "Why did delayed partial report produce only about one letter?", "What did people believe about iconic memory before Sperling, and why was it wrong?", "How does an icon differ from an echo?"], "remember": "Sensory memory has large capacity but fast decay; whole report underestimates it because the image fades while reporting."}, {"module": 6, "topic": "Duration, forgetting, and interference", "questions": ["Why did Brown and Peterson and Peterson have participants count backward by threes?", "What happened to recall after a long delay on the first trial versus many trials later?", "Which concept is this an example of: earlier trigrams making new letters harder to recall?", "How does retroactive interference differ from proactive interference?", "Why does the average over all trials give a misleading impression?"], "remember": "Counting blocks rehearsal; the trial-by-trial pattern shows proactive interference, so forgetting is both decay and interference."}, {"module": 6, "topic": "Capacity, visual memory, and chunking", "questions": ["What did Miller propose about short-term memory capacity?", "What did Alvarez and Cavanagh find as object complexity increased?", "What was manipulated in Chase and Simon's chess study, and what was found?", "What did Ericsson's trained student do to reach a digit span of around eighty?", "How does chunking increase capacity without enlarging the store?"], "remember": "Capacity is about units, not raw items: visual memory holds about three to four objects, fewer if complex, and chunking uses long-term knowledge to pack more into each slot."}, {"module": 9, "topic": "Working-memory model and component functions", "questions": ["What did Baddeley and Hitch (1974) propose?", "What does the central executive do, compared with the phonological loop?", "Why does mental multiplication of 43 times 6 need both storage and processing?", "What component did Baddeley add in 2000?", "How does the working-memory model differ from Atkinson and Shiffrin's short-term memory?"], "remember": "Working memory stores and manipulates information using a central executive, phonological loop, and visuospatial sketchpad, with the episodic buffer added later."}, {"module": 9, "topic": "Verbal maintenance, recoding, and interference", "questions": ["What did Conrad (1964) find about errors with seen letters?", "What was manipulated in Conrad's study?", "What is the word-length effect, and who found it?", "Why did Welsh-English bilingual children have a shorter digit span in Welsh (Ellis and Hennelly, 1980)?", "What does articulatory suppression do to the word-length and phonological similarity effects?"], "remember": "Seen letters are recoded into sound, and verbal span depends on rehearsal time; speaking while memorizing disrupts the loop."}, {"module": 9, "topic": "Spatial representations and Brooks’s response reversal", "questions": ["What did Brooks (1968) find about the sentence task and the F task?", "What was manipulated in Brooks's experiments?", "Why was pointing easier for the sentence but speaking easier for the F?", "What does the reversal suggest about verbal and visuospatial memory?", "Which component is used when holding the shape of an F in mind?"], "remember": "A response is harder when it uses the same kind of memory as the task: sentence with speaking, F with pointing."}, {"module": 9, "topic": "Mental rotation and executive control", "questions": ["What did Shepard and Metzler (1971) find about angle and reaction time?", "What is the difference between picture-plane and depth rotation?", "What are Miyake and colleagues' (2000) updating, shifting, and inhibition?", "Why is the central executive sometimes criticized as a homunculus?", "Which concept is this an example of: suppressing irrelevant information to keep the current goal?"], "remember": "Reaction time rises with rotation angle, and the central executive controls attention through updating, shifting, and inhibition."}, {"module": 9, "topic": "Integrated episodes and filtering individual differences", "questions": ["What does the episodic buffer do and what is its capacity?", "What did Vogel and colleagues (2005) find for high-capacity versus low-capacity participants when distractors were added?", "What was manipulated in Vogel's task?", "How is filtering efficiency related to working-memory capacity?", "Why can some amnesic patients immediately recall a just-heard story?"], "remember": "The buffer binds loop, sketchpad, and long-term information into episodes; higher capacity goes with better filtering of distractors."}, {"module": 10, "topic": "Problem representation, restructuring, and insight", "questions": ["What are the present state, goal, and obstacle in a problem?", "What did Metcalfe and Wiebe (1987) find about warmth ratings for algebra versus insight problems?", "What was manipulated in Metcalfe and Wiebe's study?", "What is restructuring, and how does it solve Köhler's circle problem?", "How does the triangle problem or chain problem require a change in representation?"], "remember": "A problem has a present state, goal, and obstacle; insight follows restructuring and feels sudden, unlike gradual algebra."}, {"module": 10, "topic": "Fixation, functional fixedness, and mental set", "questions": ["What did the empty matchbox condition change in the candle problem?", "What is functional fixedness, and how does it apply to the pliers in the two-string problem?", "What is a mental set, and how does the water-jug procedure B − A − 2C illustrate it?", "Which concept is this an example of: failing to see a simpler solution because a familiar method worked before?", "How does fixation differ from a mental set?"], "remember": "Functional fixedness is about an object's familiar use; mental set is about a familiar method. Both hide a workable solution."}, {"module": 10, "topic": "Problem spaces, operators, and means–end analysis", "questions": ["What are the initial state, intermediate states, and goal state in a problem space?", "What do operators do in the Tower of Hanoi?", "What is a subgoal, and what are the Tower of Hanoi subgoals?", "What does means–end analysis try to reduce?", "What does a search tree show for the tile puzzle?"], "remember": "Newell and Simon describe solving as search through states using operators; means–end analysis reduces the gap to the goal by achieving subgoals."}, {"module": 10, "topic": "Checkerboard representations and think-aloud evidence", "questions": ["Why can 31 dominoes not cover the mutilated checkerboard?", "What conditions were compared in the checkerboard experiment, and what was found?", "How did the bread-and-butter labels help solvers?", "What is a think-aloud protocol, and what does it reveal?", "Which concept is this an example of: a change in representation that makes a constraint available?"], "remember": "Opposite corners are the same color, so colors are unequal; labels like bread and butter made the pairing constraint easier to see, and solving was twice as fast as blank."}, {"module": 11, "topic": "Analogical sources, targets, and convergence", "questions": ["What is the difference between a source problem and a target problem?", "In the Russian marriage problem, what do the marriages and the groups of people correspond to in the checkerboard problem?", "What solution did Duncker's radiation problem require, and what percentage solved it without the analogy?", "Which concept is this an example of: sending small groups along different roads so they arrive together at the fortress?", "How did the percentage solving radiation change after reading the fortress story, and after being told to think about it?"], "remember": "Both the fortress and radiation solutions use weak approaches that converge to give a strong effect at one target. Noticing the source is the hard step."}, {"module": 11, "topic": "Noticing, surface similarity, and structural correspondence", "questions": ["What did 81% versus 10% show in the lightbulb study?", "What is the difference between surface features and structural features?", "Why did the fragile-glass source (69%) help more than the insufficient-intensity source (33%) on radiation?", "What is analogical encoding?", "Which concept is this: noticing, mapping, or applying: connecting the central target to the separate approaches?"], "remember": "Matching structure (a strong effect at the target and protected surroundings) matters more than matching objects, though similar surfaces help noticing."}, {"module": 11, "topic": "Real-world analogy and research conditions", "questions": ["What is the analogical paradox?", "How many analogies do scientists use in a one-hour lab meeting?", "What is in vivo problem-solving research?", "What is one tradeoff of in vivo research compared with a lab experiment?"], "remember": "Analogies are hard to transfer in the lab but common in real work (about 3-15 per meeting). In vivo trades control for real context."}, {"module": 11, "topic": "Expert knowledge, chunks, and problem organization", "questions": ["What did Chase and Simon (1973) find about experts and random chess arrangements?", "What is a chunk?", "How did novices and experts sort the physics problems in Chi et al. (1982)?", "Which concept explains why an expert groups problems 21 and 24 together?", "Do experts outperform novices outside their field?"], "remember": "Experts rely on organized knowledge (chunks, principles) within their field. Outside the field they are no better than novices."}, {"module": 11, "topic": "Creativity, divergent thinking, and implementing solutions", "questions": ["What is divergent thinking?", "What stages come after generating ideas in creative problem solving?", "How can too much knowledge hinder creative problem solving?", "What does thinking flexibly require when a familiar procedure does not fit?"], "remember": "Ideas are necessary but not enough. Evaluation, planning, and implementation are separate parts. Familiar procedures can block flexibility."}, {"module": 12, "topic": "Judgments, decisions, and inductive evidence", "questions": ["What is the difference between decisions and reasoning?", "What is inductive reasoning?", "What three things determine the strength of an inductive argument?", "How does the black swan example show the weight of one high-quality observation?", "Why are inductive conclusions only probably true?"], "remember": "Decisions choose between alternatives. Reasoning draws conclusions. Induction goes from observations to probable conclusions."}, {"module": 12, "topic": "Availability, representativeness, and sample size", "questions": ["What did people choose in the r-first versus r-third word question, and what is the truth?", "What is base-rate neglect, and how does the Jack problem show it?", "Why is choosing feminist bank teller for Linda a conjunction error?", "What is the correct answer to the hospital question, and why?", "What does the law of large numbers say?"], "remember": "Availability uses ease of remembering. Representativeness uses resemblance. Small samples vary more than large ones."}, {"module": 12, "topic": "Illusory correlation, myside bias, and hypothesis testing", "questions": ["What is an illusory correlation?", "How does a stereotype connect to the availability heuristic?", "What did Lord and colleagues (1979) find about people who favored or opposed capital punishment?", "What is the difference between confirmation bias and myside bias?", "What was the actual rule in the 2, 4, 6 task, and what hypothesis was most common?"], "remember": "People look for and favor information that fits what they already believe, and rarely test what could disprove it."}, {"module": 12, "topic": "Utility, probabilities, and choices that cause harm", "questions": ["What does expected utility theory assume people do?", "Why do utility procedures not fully describe real choices (for example, casino gambling)?", "In the jellybean choice, which bowl did most people pick and which has the higher probability?", "What did Ritov and Baron (1999) find about rerouting the convoy?", "How did avoiding air travel after September 11 increase harm?"], "remember": "People do not always maximize expected benefit. They are swayed by counts, harm avoidance, and fear."}, {"module": 12, "topic": "Sacred values, taboo and tragic tradeoffs", "questions": ["What is a sacred value, and how is it kept separate from secular values?", "What is the difference between a taboo tradeoff and a tragic tradeoff?", "What did Tetlock and colleagues (2000) find about outrage when Johnny was not saved in each tradeoff?", "Which tradeoff produced similar outrage whether Johnny was saved or not?"], "remember": "Taboo mixes sacred with secular and causes outrage. Tragic compares two sacred values, so outcome matters less."}, {"module": 12, "topic": "Sacred values in intergroup negotiation", "questions": ["Who were the participants in Ginges, Atran, Medin, and Shikaki (2007)?", "What was added in Taboo+, and what was added in the symbolic version?", "How did moral absolutists and non-absolutists differ in response to money?", "What percentage of settlers held the sacred-value position on the Land of Israel?", "How did symbolic recognition compare with money for anger and support for violence?"], "remember": "For sacred issues money can backfire (more anger and support for violence), while symbolic reciprocity helps."}, {"module": 12, "topic": "Nuclear-program study, manipulations, measures, and energy results", "questions": ["What is the design of the Iranian online study (Dehghani and colleagues)?", "What do Taboo, Taboo+, and Taboo- each involve?", "How was a sacred value classified, and how many participants did so?", "What did sacred-value participants show for approval and anger with funds or sanctions in the energy condition?", "What three judgments did participants make?"], "remember": "Funds and sanctions did not raise approval for sacred-value participants and raised anticipated anger. Non-sacred participants barely changed."}, {"module": 13, "topic": "Emotions, expected emotions, and risk aversion", "questions": ["What did Kermer and colleagues (2006) find about expected versus actual emotions after a loss?", "What was manipulated in Kermer and colleagues (2006)?", "How do expected emotions relate to risk aversion?", "Why do people overestimate how bad a loss will feel?", "How do flattened emotions, anxiety, and optimism each affect decision making?"], "remember": "People expect a loss to hurt more than an equal gain helps, but coping mechanisms make the real feeling smaller; this raises risk aversion."}, {"module": 13, "topic": "Incidental emotions and mood", "questions": ["What did Simonsohn (2007) find about cloudy days and admissions?", "What did Simonsohn (2009) find about campus visits?", "What was manipulated in Lerner and colleagues (2004)?", "What did Lerner and colleagues (2004) find about buying and selling prices for sad and disgust groups?", "Which concept is this an example of: a film clip changes how much a highlighter seems worth?"], "remember": "Incidental emotions come from unrelated things (weather, clips) yet change decisions."}, {"module": 13, "topic": "Context, defaults, and the status quo bias", "questions": ["What was manipulated in the physician cesarean study?", "Which group of physicians recommended cesarean more often, and why?", "How do opt-in and opt-out differ, and what consent rates result?", "Which concept is this an example of: people leaving the default organ donor choice unchanged?"], "remember": "Context and defaults shape choices; status quo bias is doing nothing, so the default wins."}, {"module": 13, "topic": "Framing gains and losses", "questions": ["What did Tversky and Kahneman (1981) find in the gain frame?", "What did Tversky and Kahneman (1981) find in the loss frame?", "How are Programs A and C related?", "Which strategy does a gain frame encourage, and which does a loss frame encourage?", "How does risk aversion differ from risk taking?"], "remember": "Same outcomes, different words: gain frame gives sure option (72% A), loss frame gives gamble (78% D)."}, {"module": 13, "topic": "Neuroeconomics and the ultimatum game", "questions": ["What did Sanfey and colleagues (2003) find about human versus computer offers?", "What does utility theory say the responder should do?", "What did Sanfey and colleagues (2003) find about the right anterior insula?", "What is neuroeconomics?"], "remember": "Responders reject unfair offers out of anger, even at a cost; insula activity tracks rejecting."}, {"module": 13, "topic": "Deductive reasoning, validity, and belief bias", "questions": ["What is a syllogism and what are its parts?", "How does validity differ from truth?", "What is belief bias, and what percent judged invalid believable syllogisms as valid?", "Which concept is this an example of: All birds are animals, All animals have four legs, All birds have four legs?", "Is this valid: All of the students are tired, Some tired people are irritable, Some of the students are irritable?"], "remember": "Valid means it follows from the premises, not that it is true. Belief bias confuses believable with valid."}, {"module": 13, "topic": "Mental models", "questions": ["What is a mental model according to Johnson-Laird (1999)?", "What are the steps of the mental model approach?", "When is a conclusion valid under the mental model approach?", "Why does imagining the pool table help?"], "remember": "Build a picture, draw a tentative conclusion, search for an exception; one exception means not valid."}, {"module": 13, "topic": "Conditional syllogisms", "questions": ["What is modus ponens and how many judged it correctly?", "What is modus tollens and why is it harder?", "Why is If p then q, q, therefore p not valid?", "Why is If p then q, not p, therefore not q not valid?", "Which two of the four conditional syllogisms are valid?"], "remember": "Valid: p so q (97%), not q so not p (60%). Invalid: q so p and not p so not q (40% each)."}, {"module": 13, "topic": "The Wason four-card problem and permission schemas", "questions": ["Which cards should be turned over in the E, K, 4, 7 problem, and why?", "What is the falsification principle?", "What happened in the concrete beer version?", "What is a permission schema?", "How does the abstract version differ from the concrete version?"], "remember": "Test a rule by looking for what could break it: E and 7; beer and 16. Permission schemas make the concrete version easier."}, {"module": 14, "topic": "Phonological Similarity Effect", "questions": ["What is the phonological similarity effect?", "What was manipulated when people said 'one, two, three, four' out loud?", "Which concept is this an example of: mix-ups between E and F would show a visual code, but sound-alike mix-ups show...?"], "remember": "Sound-alike items hurt recall even when read silently, so we recode into speech."}, {"module": 14, "topic": "Neighborhood Size Effect", "questions": ["What did Roodenrys et al. (2002) find about large neighborhood words?", "What is a word's neighborhood?", "Why is memory span not a pure measure of short-term capacity?"], "remember": "Long-term word knowledge helps short-term recall."}, {"module": 14, "topic": "Brown-Peterson Task", "questions": ["What did Peterson and Peterson (1959) conclude about forgetting in short-term memory?", "What was manipulated in the Brown-Peterson task?", "Which concept is this an example of: forgetting because information fades unless rehearsed?"], "remember": "Longer distraction, worse recall: the authors said decay."}, {"module": 14, "topic": "Modality Effect", "questions": ["What is the modality effect?", "What was compared in the modality effect?", "What explanation do Neath and Surprenant (2003) favor?"], "remember": "Heard lists give better memory for the last items."}, {"module": 14, "topic": "Partial Report", "questions": ["What did Sperling (1960) find with the cue right after the display?", "What was manipulated in partial report?", "Which concept is this an example of: a very brief store holding nearly all of a display?"], "remember": "The limit is reporting time because the sensory store fades fast."}, {"module": 14, "topic": "Position Error Effect", "questions": ["What is the position error effect?", "Where do misplaced items usually end up?", "Why does scoring only percent correct hide something?"], "remember": "Order errors are systematic, not random."}, {"module": 14, "topic": "Mental Rotation", "questions": ["What did Shepard and Metzler (1971) find about turning the shape?", "What was manipulated in the mental rotation task?", "Why do researchers use tasks that require imagery instead of self-reports?"], "remember": "Bigger turn, longer response: mental images are like real images."}, {"module": 14, "topic": "Typical Reasoning", "questions": ["What did Tversky and Kahneman (1983) show about probability estimates?", "What did Shafir, Smith, and Osherson (1990) find?", "Which concept is this an example of: judging A and B together as more likely than A alone?"], "remember": "A combination is never more likely than a part: the conjunction fallacy shows heuristics."}, {"module": 14, "topic": "Wason Selection", "questions": ["Which two cards best test the rule 'If a card has a D on one side, it has a 3 on the other', and why?", "What did Wason and Shapiro (1971) compare?", "Why is the car and gas tank rule easier?"], "remember": "Look for what could falsify the rule; experience helps."}, {"module": 14, "topic": "Decision Making", "questions": ["What is a framing effect?", "What was manipulated in classic framing research?", "Which concept is this an example of: gain wording leading to the sure option?"], "remember": "Same choice, different wording, different decision."}, {"module": 14, "topic": "Monty Hall", "questions": ["Should you stay or switch in the Monty Hall problem, and why?", "What is wrong with thinking the two remaining doors are equal?", "What chance does the first pick keep?"], "remember": "Switching wins about two-thirds of the time."}, {"module": 14, "topic": "Risky Decisions", "questions": ["What do people typically do with gains in risky choices?", "What do people typically do with losses?", "What was varied in the risky decisions task?"], "remember": "Gains lead to the sure thing; losses lead to the gamble."}, {"module": 14, "topic": "German & Defeyter (2000): Immunity to functional fixedness in young children", "questions": ["What did German and Defeyter (2000) find about 5-year-olds?", "What was manipulated in German and Defeyter (2000)?", "Which concept is this an example of: being stuck on an object's usual function?"], "remember": "Younger children are more fluid, so one shown use did not lock the box in."}, {"module": 14, "topic": "Leist et al. (2022): Irrelevant speech impairs serial recall of verbal but not spatial items", "questions": ["What did Leist et al. (2022) find about spatial recall?", "What was manipulated in Leist et al. (2022)?", "Which concept is this an example of: speech that hurts recall of ordered items?"], "remember": "Ignored speech hurts verbal, not spatial, recall."}, {"module": 14, "topic": "Morrison & Richmond (2020): Offloading items from memory", "questions": ["What did Morrison and Richmond (2020) find about offloading and high loads?", "What was manipulated in Morrison and Richmond (2020)?", "Did memory ability predict who offloaded?"], "remember": "Offloading helps, mostly at high loads, across abilities."}, {"module": 14, "topic": "Hoover & Healy (2019): The Bat-and-Ball Problem", "questions": ["What did Hoover and Healy (2019) find about 'more than'?", "What was manipulated in Hoover and Healy (2019)?", "Why do they call it error sensitivity?"], "remember": "Wrong reasoners mostly remembered 'more than'; substitution is not confirmed."}, {"module": 14, "topic": "Giuliani et al. (2023): The joint effect of framing and defaults on choice behavior", "questions": ["What did Giuliani et al. (2023) find about a risky default?", "What was manipulated in Giuliani et al. (2023)?", "What did the authors find about framing and default effects together?"], "remember": "Risky default raised risk taking; the two effects added up."}, {"module": 14, "topic": "Chein et al. (2011) and Albert, Chein & Steinberg (2013): Peers and the adolescent brain", "questions": ["What did Chein et al. (2011) find when friends watched the driving game?", "What did the cognitive-control regions do with peers?", "What do Albert, Chein and Steinberg (2013) say raises adolescent risk taking?"], "remember": "The peer context works through reward circuitry."}], "explainers": [{"module": 9, "title": "Mental multiplication: 43 times 6", "plain": "This shows storage and processing working together: you hold one number while you work on another.", "steps": ["3 x 6 = 18.", "Hold the 8 in memory and carry the 1 over the 4.", "6 x 4 = 24, then add the carried 1 to get 25.", "Combine the 25 with the held 8 to get 258."], "example": "Holding the 8 is storage; carrying the 1 and doing the next multiplication and addition is processing.", "watchOut": "Do not say working memory only holds numbers; the 8 must survive while other operations are done."}, {"module": 10, "title": "Tower of Hanoi with subgoals", "plain": "You cannot move the big disk until it is free and the target peg is free, so you set up those conditions first.", "steps": ["Goal: move the large disk to the third peg.", "Subgoal 1: free the large disk by moving the smallest disk to the third peg and the next disk to the middle peg.", "Subgoal 2: free the third peg by moving the smallest disk from the third peg onto the smaller stack on the middle peg.", "Subgoal 3: move the largest disk from the starting peg to the third peg.", "Then move the smaller disks onto it, never putting a larger disk on a smaller one."], "example": "The slide's example: the smallest disk goes to the third peg, the next disk to the middle peg, then the smallest goes onto the middle stack.", "watchOut": "Achieving a subgoal is not the finished puzzle; the smaller disks still have to reach the third peg."}, {"module": 10, "title": "Mutilated checkerboard", "plain": "Each domino covers one square of each color, so the board must have equal numbers of the two colors.", "steps": ["A full board has 64 squares and takes 32 dominoes.", "Remove two opposite corners and 62 squares remain, matching 31 dominoes in area.", "Every domino covers one square of each color.", "Opposite corners are the same color, so one color now has fewer squares.", "Equal numbers are needed, so no covering is possible."], "example": "The bread-and-butter labels make it clear that each domino needs one bread and one butter.", "watchOut": "Equal area (62 squares, 31 dominoes) does not guarantee a legal covering."}, {"module": 10, "title": "Chain problem", "plain": "Treat a whole section of chain as the source of connectors instead of opening one link at a time.", "steps": ["Opening a link costs 2 cents and closing it costs 3 cents, so opening and closing one link costs 5 cents.", "The budget is 15 cents, so you can open and close three links.", "Open the three links of one three-link section.", "Use each opened link to join the other three sections into a closed loop, closing each once."], "example": "Four short sections become one closed loop for exactly 15 cents.", "watchOut": "Opening and closing one link costs 5 cents, so 15 cents allows only three links; use one whole section as the connectors."}, {"module": 10, "title": "Triangle problem", "plain": "Move three dots from a ten-dot upward triangle so it points down, keeping seven in place.", "steps": ["Start with ten dots in four rows, with the point on top.", "Move the original top dot to a new bottom point beneath the center of the original bottom row.", "Move the two outer dots of the original bottom row to the outer ends of the original two-dot row.", "That row now has four dots, with three, two, and one below it."], "example": "Only three dots move and seven stay put, giving a downward-pointing triangle.", "watchOut": "Moving the whole arrangement breaks the rule that seven dots stay in place."}, {"module": 10, "title": "Water-jug problems and mental set", "plain": "A rule that worked on early problems can stop you seeing a shorter route later.", "steps": ["Early problems use B − A − 2C, for example 127 − 21 − 3 − 3 = 100.", "Problem 7 (A 15, B 39, C 3, goal 18): the familiar way is 39 − 15 − 6 = 18, but A + C gives 18 directly.", "Problem 8 (A 28, B 59, C 3, goal 25): A − C gives 25 directly, although B − A − 2C also works."], "example": "Problem 8: 28 − 3 = 25 is simpler than the familiar method.", "watchOut": "The familiar method still works in problems 7 and 8; the issue is that it blocks the simpler one."}, {"module": 11, "title": "Pairing problems: marriage and checkerboard", "plain": "Count the two kinds of pieces that must pair up. If the counts differ, a full pairing is impossible.", "steps": ["Find what each pair must contain (one man and one woman, or one square of each color).", "Count each kind.", "Compare the counts, not the total.", "If unequal, some are left over, however you rearrange."], "example": "30 men and 32 women give at most 30 marriages. Removing two same-colored corners leaves unequal colors, so 31 dominoes cannot cover the board.", "watchOut": "Do not use total size (62 divided by 2 = 31)."}, {"module": 11, "title": "Converging solution (radiation, fortress, lightbulb)", "plain": "Split a strong effect into weak parts that travel separately and meet at the target.", "steps": ["Find the target that needs a strong effect.", "Find the limit on the paths (healthy tissue, mines, fragile glass).", "Use several weak approaches from different directions.", "Make them arrive together."], "example": "Several low-intensity rays hit the tumor at once. Each path is safe, and the combined intensity destroys it.", "watchOut": "Dividing without combining at the same time does not work."}, {"module": 12, "title": "Base rates and Jack", "plain": "Start with how common each category is, then adjust for the description, instead of ignoring the numbers.", "steps": ["Write the base rate (70 lawyers, 30 engineers).", "With no description, the chance of an engineer is 30 out of 100.", "With a description, remember the group still has more lawyers.", "Do not decide on fit alone."], "example": "Jack is conservative, careful, and enjoys home carpentry and math puzzles. People say engineer, yet the group is 70 lawyers.", "watchOut": "A good-fitting description does not settle the probability."}, {"module": 12, "title": "Conjunction rule (Linda)", "plain": "Adding a condition can only shrink the set, so a combination is never more likely than one part.", "steps": ["Name the two events (bank teller, feminist bank teller).", "See that feminist bank tellers are inside bank tellers.", "The smaller set cannot be more probable."], "example": "About 82% chose feminist bank teller, but bank teller alone must be at least as probable.", "watchOut": "A more detailed story feels more likely but is not."}, {"module": 12, "title": "Sample size (hospital question)", "plain": "Small samples swing more, so extreme proportions happen more often in them.", "steps": ["Note the sample sizes (about 15 versus 45 births a day).", "Note the true rate is about 50% boys in both.", "Ask which sample can stray more from 50%.", "Pick the smaller one."], "example": "The smaller hospital has more days over 60% boys. 56% wrongly said about the same.", "watchOut": "Do not confuse total boys with the share of days above 60%."}, {"module": 12, "title": "Probability as a ratio (jellybeans)", "plain": "Chance of winning is winning items divided by total items, not the count of winning items.", "steps": ["Write each bowl as red out of total.", "Convert to a percentage.", "Compare the percentages."], "example": "1 out of 10 is 10%. 7 out of 100 is 7%. So the first bowl is better, although most picked the second.", "watchOut": "A bigger count of red beans hides the larger total."}, {"module": 12, "title": "Expected utility", "plain": "Weigh how good each outcome is by how likely it is, then choose the best total.", "steps": ["List the alternatives.", "Rate the value of each outcome.", "Combine value with chance.", "Choose the maximum expected utility."], "example": "Casino gambling shows people choosing an activity despite knowing the odds are against them.", "watchOut": "People value things other than money, so the theory does not fully describe choices."}, {"module": 12, "title": "Inductive evidence strength", "plain": "Inductive conclusions are probably true, and they are stronger with better observations.", "steps": ["Check how representative the observations are.", "Check how many there are.", "Check how good (compelling) each one is.", "Allow that one strong case can contradict a claim."], "example": "Many white swans support the claim that all swans are white, but one clearly observed black swan contradicts it.", "watchOut": "More observations is not the only factor. Quality counts."}, {"module": 13, "title": "What a syllogism is and its parts", "plain": "A syllogism is the basic form of deductive reasoning, introduced by Aristotle. It has two premises and a conclusion.", "steps": ["1. Find the two premises: the statements the reasoning starts from.", "2. Find the conclusion: the third statement, what you arrive at.", "3. Ask only one thing: does the conclusion follow from the two premises?"], "example": "Premise 1: All birds are animals. Premise 2: All animals eat food. Conclusion: Therefore, all birds eat food. Birds are inside animals, animals are inside things that eat food, so birds are inside that group too.", "watchOut": "A categorical syllogism uses all, no, or some about two categories. Do not mix it up with the conditional syllogism, which starts with If p, then q."}, {"module": 13, "title": "How to check validity, step by step", "plain": "There is no easy method, so picture the situation the premises describe and try to break the conclusion (the mental model approach).", "steps": ["1. Build a picture (model) of the situation the two premises describe.", "2. Write a tentative conclusion, one that might hold.", "3. Look for an exception: a case where the premises are true but the conclusion is not.", "4. If you find one exception, the syllogism is not valid. If no model of the premises refutes the conclusion, it is valid."], "example": "All of the students are tired; Some tired people are irritable; so Some of the students are irritable. Everything sounds reasonable, but the conclusion does not follow from the premises, so the syllogism is not valid.", "watchOut": "Do not stop at the first model that fits. A conclusion is valid only if NO model of the premises refutes it."}, {"module": 13, "title": "Validity versus truth", "plain": "Valid means the conclusion follows from the premises. True means the statement matches the world. They are different.", "steps": ["1. Ignore whether the statements sound true.", "2. Check only the form: does the conclusion follow from the two premises?", "3. Then separately ask whether each statement is actually true.", "4. Remember: valid plus true premises forces a true conclusion; valid with a false premise can give a false conclusion."], "example": "All birds are animals; All animals have four legs; All birds have four legs. It has the same form as the first example, so it is valid. The conclusion is false only because premise 2 is false.", "watchOut": "A syllogism can be invalid even if every statement and the conclusion seem reasonable (the students example). Valid does not guarantee a true conclusion."}, {"module": 13, "title": "Belief bias", "plain": "Belief bias is thinking a syllogism is valid just because its conclusion is believable.", "steps": ["1. Notice if your gut says the conclusion is true.", "2. Set that feeling aside.", "3. Check whether the conclusion follows from the premises (look for an exception).", "4. Judge validity from that, not from belief."], "example": "71% of participants judged invalid syllogisms with believable conclusions as valid. All of the students are tired; Some tired people are irritable; Some of the students are irritable sounds right but is not valid.", "watchOut": "Good reasoning and truth are not the same thing; do not accept reasoning just because the ending sounds true."}, {"module": 13, "title": "Conditional syllogisms: the four forms cheat sheet", "plain": "All four start with If p, then q. p is the condition and q is what follows. They differ in the second premise.", "steps": ["1. Write the first premise as If p, then q.", "2. Identify the second premise: p, not q, q, or not p.", "3. Match it: p so q (valid); not q so not p (valid); q so p (not valid); not p so not q (not valid).", "4. Valid forms: go forward from p, or backward from not q."], "example": "If I study, I'll get a good grade. Form 1: I studied, so I'll get a good grade (97% correct). Form 2: I didn't get a good grade, so I didn't study (60%). Form 3: I got a good grade, so I studied (40%). Form 4: I didn't study, so I didn't get a good grade (40%).", "watchOut": "Two are valid and two are not. Both valid types were judged correctly more often than both invalid ones."}, {"module": 13, "title": "Modus ponens and modus tollens (the valid ones)", "plain": "Modus ponens: the condition is met, so the result follows. Modus tollens: the result did not happen, so the condition did not happen.", "steps": ["1. Modus ponens: If p, then q; p; therefore q.", "2. Modus tollens: If p, then q; not q; therefore not p.", "3. Test tollens in words: if studying always leads to a good grade, no good grade means no studying.", "4. Both are valid with any content."], "example": "If I study, I'll get a good grade. I didn't get a good grade. Therefore, I didn't study. Valid, though only 60% judged it correctly (vs 97% for modus ponens).", "watchOut": "Modus tollens is just as valid as modus ponens, yet people find it much harder."}, {"module": 13, "title": "Why syllogisms 3 and 4 are not valid", "plain": "If p, then q says what happens when p is true. It does not say q happens only then, and it says nothing about when p is false.", "steps": ["1. Syllogism 3 (q so p): the premise does not say studying is the only way to get a good grade.", "2. Swap in other content to test it: If I live in Tucson, then I live in Arizona; I live in Arizona; so I live in Tucson fails.", "3. Syllogism 4 (not p so not q): the premise says nothing about not studying, and a good grade could come another way.", "4. If you can find a case where the premises hold but the conclusion fails, it is not valid."], "example": "Syllogism 4: If I study, I'll get a good grade; I didn't study; therefore I didn't get a good grade. A person could get a good grade for some other reason, so the conclusion does not follow.", "watchOut": "Only 40% got each of these right. The first premise does not support either conclusion."}, {"module": 13, "title": "Mental models (Johnson-Laird, 1999) and the pool table", "plain": "A mental model is a specific situation pictured in your mind that you use to judge a syllogism.", "steps": ["1. Create a model of the situation.", "2. Generate tentative conclusions about the model.", "3. Look for exceptions that falsify the model.", "4. Decide validity from whether an exception exists."], "example": "Pool table: a black ball directly above the cue ball, the green ball on the right of the cue ball, a red ball between them. The slide's answer is that the cue ball is to the left of the line of sight. Most people solve it by imagining the arrangement.", "watchOut": "One model that fits the premises but not the conclusion is enough to reject the conclusion."}, {"module": 13, "title": "The Wason four-card problem (abstract)", "plain": "To test a rule, look for cards that could break it. This is the falsification principle.", "steps": ["1. Rule: if there is a vowel on one side, then there is an even number on the other.", "2. Ask for each card: could its hidden side break the rule?", "3. E: a non-even number behind it would break the rule, so turn it. K: not a vowel, cannot break it. 4: cannot break the rule whatever is behind it. 7: a vowel behind it would break the rule, so turn it.", "4. Answer: turn E and 7."], "example": "Cards E, K, 4, 7. 46% wrongly chose 4; only 7% chose the correct 7.", "watchOut": "The 4 feels right because it fits the rule, but it cannot break the rule; most people fail to look for falsifying cases."}, {"module": 13, "title": "Concrete Wason version and permission schemas", "plain": "A permission schema is the idea that if A is satisfied, B can be carried out. Familiar rules like a drinking age call it up and make the problem easier.", "steps": ["1. Rule: If drinking beer, then 21 years old.", "2. Find the case that breaks it: someone drinking beer who is under 21.", "3. Turn over beer (check the age) and 16 years old (check the drink).", "4. Soda and 21 years old cannot break the rule."], "example": "Cards Beer, Soda, 16 years old, 21 years old. 73% answered correctly. Being 21 is the condition; drinking beer is what can then be done.", "watchOut": "The form is the same as the vowel rule. Familiarity is not always important, so the improvement does not come from familiarity alone; context that calls up a permission schema matters."}, {"module": 13, "title": "Framing effect: gain versus loss", "plain": "The same facts worded as gains or as losses change what people choose.", "steps": ["1. Gain frame (saved): sure option vs gamble; people avoid risk.", "2. Loss frame (die): sure option vs gamble; people take the risk.", "3. Check that A equals C (200 saved = 400 die) and B equals D (same gamble).", "4. Conclude that only the wording changed."], "example": "600 people at risk. A: 200 saved for certain (72% chose it); B: 1/3 chance all saved, 2/3 none. C: 400 die for certain (22%); D: 1/3 nobody dies, 2/3 all die (78%).", "watchOut": "It is a switch in strategy caused by wording alone, not a difference in the outcomes."}]};
